#include <bits/stdc++.h>
#include <ext/pb_ds/assoc_container.hpp>
#include <ext/pb_ds/tree_policy.hpp>

using namespace std;
using namespace __gnu_pbds;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    using Key = pair<long long, int>;
    tree<Key, null_type, less<Key>, rb_tree_tag, tree_order_statistics_node_update> distances;

    int previousPenalty = 0;

    for (int k = 0; k < N; ++k) {
        long long x, y;
        cin >> x >> y;

        x += previousPenalty;
        y += previousPenalty;

        long long d2 = x * x + y * y;
        int penalty = distances.order_of_key({d2, INT_MAX});

        cout << penalty << '\n';
        distances.insert({d2, k});
        previousPenalty = penalty;
    }

    return 0;
}
